import assert from 'node:assert/strict'
import { createMiniUploadProcessor } from '../src/utils/mp-upload-image-core.mjs'

// Real 1x1 WebP payloads generated by sharp: opaque VP8 and alpha VP8X/ALPH/VP8.
const opaqueWebp = Buffer.from('UklGRi4AAABXRUJQVlA4ICIAAABwAQCdASoBAAEAAUAmJZQCdAFAAAD+/DeBV/fU6D4r4AAA', 'base64')
const alphaWebp = Buffer.from('UklGRkoAAABXRUJQVlA4WAoAAAAQAAAAAAAAAAAAQUxQSAIAAAAAgFZQOCAiAAAAcAEAnQEqAQABAAFAJiWUAnQBQAAA/vw3gVf31Og+K+AAAA==', 'base64')
const encode = bytes => `data:image/webp;base64,${bytes.toString('base64')}`
const decodeBase64 = value => Buffer.from(value, 'base64')
const pause = ms => new Promise(resolve => setTimeout(resolve, ms))

function setup(patch = {}) {
  const state = {
    images: [], draws: [], fills: [], exports: [], writes: [], removed: [],
    canvasCalls: 0, encodes: [],
  }
  const canvas = {
    width: 0,
    height: 0,
    getContext() {
      return {
        clearRect() {},
        fillRect(...args) { state.fills.push({ color: canvas._fillStyle, args: [...args] }) },
        drawImage(image, ...args) { state.draws.push({ source: image.src, args: [...args] }) },
        set fillStyle(value) { canvas._fillStyle = value },
      }
    },
    createImage() {
      const image = { width: 40, height: 20, onload: null, onerror: null, _src: '' }
      Object.defineProperty(image, 'src', {
        get() { return image._src },
        set(value) {
          image._src = value
          state.images.push(value)
          const deliver = () => image.onload?.()
          if (patch.imageDelay) setTimeout(deliver, patch.imageDelay)
          else if (patch.imageError) image.onerror?.(new Error('decode failed'))
          else deliver()
        },
      })
      return image
    },
    toDataURL(mime, quality) {
      state.encodes.push({ mime, quality, width: canvas.width, height: canvas.height })
      return patch.toDataURL ? patch.toDataURL(mime, quality, state.encodes.length) : encode(opaqueWebp)
    },
  }
  const runtime = {
    timeoutMs: 500,
    getCanvas: patch.getCanvas || (options => { state.canvasCalls++; options.success({ canvas }) }),
    fs: () => ({
      writeFile(options) {
        state.writes.push(options)
        if (patch.writeFile) return patch.writeFile(options, state)
        options.success({})
      },
      unlink(options) { state.removed.push(options.filePath); options.success?.({}) },
    }),
    root: () => '/user',
    decodeBase64,
    exportCanvas(options) {
      state.exports.push(options)
      if (patch.exportCanvas) return patch.exportCanvas(options, state)
      options.success({ tempFilePath: `/tmp/fallback-${state.exports.length}.${options.fileType}` })
    },
    ...patch.runtime,
  }
  return { processor: createMiniUploadProcessor(runtime), state, canvas }
}
const info = { width: 40, height: 20, orientation: 'up' }
const opts = { quality: 80, maxSize: 256, preserveAlpha: false }

// Successful WebP export validates both the RIFF payload and written base64.
{
  const { processor, state } = setup()
  const path = await processor('/photo.jpg', info, opts)
  assert.match(path, /^\/user\/upload_mp_.*\.webp$/)
  assert.equal(state.writes.length, 1)
  assert.equal(state.writes[0].data, opaqueWebp.toString('base64'))
  assert.equal(state.writes[0].encoding, 'base64')
  await processor('/second.jpg', info, opts)
  assert.equal(state.canvasCalls, 2)
  assert.equal(state.encodes.filter(item => item.width === 2 && item.height === 1).length, 1, 'capability probe runs once per processor session')
}

// A PNG data URL from a nominal WebP request must fail capability detection.
{
  const pngLookingWebp = 'data:image/png;base64,' + opaqueWebp.toString('base64')
  const { processor, state } = setup({ toDataURL: () => pngLookingWebp })
  assert.equal(await processor('/photo.jpg', info, opts), '/tmp/fallback-1.jpg')
  assert.equal(state.writes.length, 0)
  assert.equal(state.exports[0].fileType, 'jpg')
}

// Alpha is preserved through PNG fallback without painting the canvas white.
{
  const { processor, state } = setup({ toDataURL: () => encode(opaqueWebp) })
  assert.equal(await processor('/avatar.png', info, { ...opts, preserveAlpha: true }), '/tmp/fallback-1.png')
  assert.equal(state.exports[0].fileType, 'png')
  assert.equal(state.fills.some(fill => fill.color === '#ffffff'), false)
}
{
  const { processor, state } = setup({ toDataURL: () => encode(alphaWebp) })
  assert.match(await processor('/avatar.png', info, { ...opts, preserveAlpha: true }), /^\/user\/upload_mp_.*\.webp$/)
  assert.equal(state.writes[0].data, alphaWebp.toString('base64'))
  assert.equal(state.fills.some(fill => fill.color === '#ffffff'), false)
}

// Opaque photos are flattened onto white before JPEG fallback.
{
  const { processor, state } = setup({ toDataURL: () => 'data:image/png;base64,AA==' })
  assert.equal(await processor('/photo.jpg', info, opts), '/tmp/fallback-1.jpg')
  assert.equal(state.exports[0].fileType, 'jpg')
  assert.deepEqual(state.fills.filter(fill => fill.color === '#ffffff').map(fill => fill.color), ['#ffffff'])
}

// File-system write failure falls through to the native canvas exporter.
{
  const { processor, state } = setup({ writeFile: options => options.fail(new Error('disk full')) })
  assert.equal(await processor('/photo.jpg', info, opts), '/tmp/fallback-1.jpg')
  assert.equal(state.removed.length, 1)
  assert.equal(state.exports.length, 1)
}

// Canvas acquisition, image decode, and native export API failures are contained.
{
  const { processor } = setup({ getCanvas: options => options.fail(new Error('canvas unavailable')) })
  assert.equal(await processor('/photo.jpg', info, opts), null)
}
{
  const { processor } = setup({ imageError: true })
  assert.equal(await processor('/bad-image.jpg', info, opts), null)
}
{
  const { processor } = setup({ exportCanvas: options => options.fail(new Error('export failed')), toDataURL: () => 'data:image/png;base64,AA==' })
  assert.equal(await processor('/photo.jpg', info, opts), null)
}

// A late successful write after timeout is removed rather than leaked.
{
  let finishWrite
  const { processor, state } = setup({
    runtime: { timeoutMs: 25 },
    writeFile: options => { finishWrite = options.success },
  })
  assert.equal(await processor('/slow.jpg', info, opts), null)
  const destination = state.writes[0].filePath
  finishWrite({})
  await pause(0)
  assert.ok(state.removed.includes(destination))
}

// Calls sharing one scratch canvas are serialized, including image decode.
{
  const { processor, state } = setup({ imageDelay: 8 })
  const [first, second] = await Promise.all([
    processor('/first.jpg', info, opts),
    processor('/second.jpg', info, opts),
  ])
  assert.ok(first && second)
  assert.deepEqual(state.images, ['/first.jpg', '/second.jpg'])
  assert.deepEqual(state.draws.map(draw => draw.source), ['/first.jpg', '/second.jpg'])
}

// Rotation remains on the established native path.
{
  const { processor, state } = setup()
  assert.equal(await processor('/rotated.jpg', { ...info, orientation: 'right' }, opts), null)
  assert.equal(state.canvasCalls, 0)
}

console.log('mini upload image tests passed: WebP validation/write, capability probe, alpha/JPEG fallback, failures, timeout cleanup, serialization, and orientation')
